var _ handler.Handler = (*Handler)(nil)

package dynconfig

import (
	"context"
	"encoding/json"
	"net/http"
	"os"

	"github.com/fsnotify/fsnotify"
	"github.com/spf13/viper"
	"github.com/vasu1124/introspect/pkg/assets"
	"github.com/vasu1124/introspect/pkg/handler"
	"github.com/vasu1124/introspect/pkg/logger"
	"github.com/vasu1124/introspect/pkg/version"
)

// Handler implements handler.Handler for the dynamic config endpoint.
type Handler struct {
	example   map[string]string
	ctx       context.Context
	cancelCtx context.CancelFunc
	watcher   *fsnotify.Watcher
	config    *viper.Viper
}

// New creates a new dynconfig handler.
func New() *Handler {
	h := &Handler{}
	config := viper.New()

	config.SetConfigName("example")
	config.AddConfigPath("/etc/config/")
	config.AddConfigPath("./etc/config")
	if err := config.ReadInConfig(); err != nil {
		logger.Log.Error(err, "[dynconfig] Fatal error config file")
		return h
	}

	h.config = config
	h.readConfig(config)
	return h
}

// Name implements handler.Handler.
func (h *Handler) Name() string {
	return "dynconfig"
}

// RegisterRoutes implements handler.Handler.
func (h *Handler) RegisterRoutes(mux *http.ServeMux, ctx context.Context) {
	h.ctx, h.cancelCtx = context.WithCancel(ctx)
	mux.HandleFunc("/dynconfig", h.ServeHTTP)
	logger.Log.Info("[dynconfig] registered /dynconfig")

	go h.watchConfig()
}

// ServeHTTP handles the dynconfig request.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	h.example["OSENV_EXAMPLE"] = os.Getenv("OSENV_EXAMPLE")

	configJSON, err := json.MarshalIndent(h.example, "", "  ")
	if err != nil {
		logger.Log.Error(err, "[dynconfig] json marshal error")
		configJSON = []byte("{}")
	}

	data := struct {
		assets.CommonData
		ConfigJSON string
	}{
		CommonData: assets.CommonData{Version: version.Version, Flag: version.Flag},
		ConfigJSON: string(configJSON),
	}

	if err := assets.ExecuteTemplate(w, "dynamicconfig.html", data); err != nil {
		logger.Log.Error(err, "[dynconfig] executing template")
	}
}

func (h *Handler) watchConfig() {
	watcher, err := fsnotify.NewWatcher()
	if err != nil {
		logger.Log.Error(err, "[dynconfig] setup fsnotify watcher")
		return
	}
	h.watcher = watcher
	defer watcher.Close()

	watcher.Add(h.config.ConfigFileUsed())

	for {
		select {
		case e := <-watcher.Events:
			if e.Op&fsnotify.Write == fsnotify.Write {
				logger.Log.Info("[dynconfig] config file changed", "file", e.Name)
				h.readConfig(h.config)
			}
			if e.Op&fsnotify.Remove == fsnotify.Remove {
				logger.Log.Info("[dynconfig] config file removed", "file", e.Name)
				watcher.Remove(e.Name)
				watcher.Add(e.Name)
				h.readConfig(h.config)
			}
		case err := <-watcher.Errors:
			logger.Log.Error(err, "[dynconfig] Watcher error")
		case <-h.ctx.Done():
			return
		}
	}
}

func (h *Handler) readConfig(config *viper.Viper) {
	if err := config.ReadInConfig(); err != nil {
		logger.Log.Error(err, "[dynconfig] error config file")
		return
	}
	if err := config.Unmarshal(&h.example); err != nil {
		logger.Log.Error(err, "[dynconfig] unable to unmarshal into struct")
	}
}

// Close implements graceful shutdown.
func (h *Handler) Close() error {
	if h.cancelCtx != nil {
		h.cancelCtx()
	}
	if h.watcher != nil {
		h.watcher.Close()
	}
	return nil
}

// Ensure Handler implements handler.Handler.
var _ handler.Handler = (*Handler)(nil)

package validate

import (
	"context"
	"encoding/json"
	"net/http"
	"regexp"
	"sync"

	"github.com/vasu1124/introspect/pkg/assets"
	"github.com/vasu1124/introspect/pkg/handler"
	"github.com/vasu1124/introspect/pkg/logger"
	"github.com/vasu1124/introspect/pkg/version"
	admission "k8s.io/api/admission/v1"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/types"
)

// Handler implements server.Handler for the validate endpoint.
type Handler struct {
	mu              sync.RWMutex
	admissionReviews map[types.UID]*admission.AdmissionReview
	regexp          string
}

// New creates a new validate handler.
func New() *Handler {
	return &Handler{
		admissionReviews: make(map[types.UID]*admission.AdmissionReview),
		regexp:           ".*",
	}
}

// Name implements server.Handler.
func (h *Handler) Name() string {
	return "validate"
}

// RegisterRoutes implements server.Handler.
func (h *Handler) RegisterRoutes(mux *http.ServeMux, ctx context.Context) {
	mux.HandleFunc("/validate", h.ServeHTTP)
	logger.Log.Info("[validate] registered /validate")
}

// ServeHTTP handles both the webhook and the UI.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.UserAgent() != "kube-apiserver-admission" {
		h.userUI(w, r)
	} else {
		h.validate(w, r)
	}
}

func (h *Handler) userUI(w http.ResponseWriter, r *http.Request) {
	logger.Log.Info("[validate] rendering ui")

	h.mu.RLock()
	regexp := h.regexp
	h.mu.RUnlock()

	if r.Method == "POST" {
		err := r.ParseForm()
		if err != nil {
			logger.Log.Error(err, "[validate] error parsing form")
		}
		if r.Form["Regexp"] != nil {
			h.mu.Lock()
			h.regexp = r.Form["Regexp"][0]
			h.mu.Unlock()
			logger.Log.Info("[validate] setting Regexp", "RegExp", h.regexp)
		}
	}

	data := struct {
		assets.CommonData
		Regexp string
	}{
		CommonData: assets.CommonData{Version: version.Version, Flag: version.Flag},
		Regexp:     regexp,
	}

	if err := assets.ExecuteTemplate(w, "validate.html", data); err != nil {
		logger.Log.Error(err, "[validate] executing template")
	}
}

func (h *Handler) validate(w http.ResponseWriter, r *http.Request) {
	logger.Log.Info("[validate] rendering webhook")

	ar := new(admission.AdmissionReview)
	err := json.NewDecoder(r.Body).Decode(ar)
	if err != nil {
		logger.Log.Error(err, "[validate] error decoding")
		h.handleError(w, nil, err)
		return
	}

	response := &admission.AdmissionResponse{
		Allowed: true,
		UID:     ar.Request.UID,
	}
	pod := &corev1.Pod{}
	if err := json.Unmarshal(ar.Request.Object.Raw, pod); err != nil {
		logger.Log.Error(err, "[validate] error unmarshalling")
		h.handleError(w, nil, err)
		return
	}

	re := regexp.MustCompile(h.getRegexp())

	for _, c := range pod.Spec.Containers {
		if !re.MatchString(c.Image) {
			response.Allowed = false
			break
		}
	}

	responseAR := &admission.AdmissionReview{
		TypeMeta: metav1.TypeMeta{
			Kind:       "AdmissionReview",
			APIVersion: "admission.k8s.io/v1",
		},
		Response: response,
	}
	ar.Response = response

	h.mu.Lock()
	h.admissionReviews[ar.Request.UID] = ar
	// Keep map bounded - remove oldest if over 128 entries
	if len(h.admissionReviews) > 128 {
		for k := range h.admissionReviews {
			delete(h.admissionReviews, k)
			break
		}
	}
	h.mu.Unlock()

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(responseAR)
}

func (h *Handler) getRegexp() string {
	h.mu.RLock()
	defer h.mu.RUnlock()
	return h.regexp
}

func (h *Handler) handleError(w http.ResponseWriter, ar *admission.AdmissionReview, err error) {
	w.WriteHeader(http.StatusOK)
	if err != nil {
		logger.Log.Error(err, "[validate] error webhook")
	}

	response := &admission.AdmissionResponse{
		Allowed: false,
	}
	if ar != nil {
		response.UID = ar.Request.UID
	}

	ar.Response = response
	json.NewEncoder(w).Encode(ar)
}

// Ensure Handler implements handler.Handler.
var _ handler.Handler = (*Handler)(nil)

package mandelbrot

import (
	"bytes"
	"context"
	"image"
	"image/color"
	"image/gif"
	"image/png"
	"math"
	"math/cmplx"
	"net/http"
	"strconv"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/vasu1124/introspect/pkg/assets"
	"github.com/vasu1124/introspect/pkg/logger"
	"github.com/vasu1124/introspect/pkg/version"
	"github.com/vasu1124/introspect/pkg/handler"
)

var (
	requestCount = prometheus.NewCounterVec(
		prometheus.CounterOpts{
			Name: "mandelbrot_requests_total",
			Help: "Total number of requests to mandelbrot endpoint",
		},
		[]string{"proto"},
	)
	requestDuration = prometheus.NewHistogramVec(
		prometheus.HistogramOpts{
			Name:    "mandelbrot_request_duration_seconds",
			Help:    "Request duration for mandelbrot endpoint",
			Buckets: prometheus.DefBuckets,
		},
		[]string{"proto"},
	)
)

func init() {
	prometheus.MustRegister(requestCount, requestDuration)
}

// Handler implements server.Handler for the mandelbrot endpoint.
type Handler struct{}

// New creates a new mandelbrot handler.
func New() *Handler {
	return &Handler{}
}

// Name implements server.Handler.
func (h *Handler) Name() string {
	return "mandelbrot"
}

// RegisterRoutes implements server.Handler.
func (h *Handler) RegisterRoutes(mux *http.ServeMux, ctx context.Context) {
	mux.HandleFunc("/mandelbrot/view", h.ServeView)
	mux.Handle("/mandelbrot", h)
	logger.Log.Info("[mandelbrot] registered /mandelbrot/view and /mandelbrot")
}

// ServeHTTP handles the mandelbrot image generation.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	start := time.Now()
	defer func() {
		duration := time.Since(start).Seconds() * 1e3
		proto := strconv.Itoa(r.ProtoMajor) + "." + strconv.Itoa(r.ProtoMinor)
		requestCount.WithLabelValues(proto).Inc()
		requestDuration.WithLabelValues(proto).Observe(duration)
	}()

	if err := r.ParseForm(); err != nil {
		logger.Log.Error(err, "[mandelbrot] ParseForm error")
	}

	var xmin, ymin, xmax, ymax float64
	xmin = form2float64(r.Form["xmin"], -1.8)
	ymin = form2float64(r.Form["ymin"], -1.5)
	xmax = form2float64(r.Form["xmax"], 1.2)
	ymax = form2float64(r.Form["ymax"], 1.5)

	if r.Form["steps"] == nil {
		img := mandelbrot(xmin, ymin, xmax, ymax)
		png.Encode(w, img)
	} else {
		var steps, xfmin, yfmin, xfmax, yfmax float64
		xfmin = form2float64(r.Form["xfmin"], -1.110)
		yfmin = form2float64(r.Form["yfmin"], 0.228)
		xfmax = form2float64(r.Form["xfmax"], -1.106)
		yfmax = form2float64(r.Form["yfmax"], 0.232)
		steps = form2float64(r.Form["steps"], 10)

		var images []*image.Paletted
		var delays []int
		for i := 0.0; i <= steps; i += 1.0 {
			img := mandelbrot(
				xmin+(xfmin-xmin)*math.Tanh(4*i/steps),
				ymin+(yfmin-ymin)*math.Tanh(4*i/steps),
				xmax+(xfmax-xmax)*math.Tanh(4*i/steps),
				ymax+(yfmax-ymax)*math.Tanh(4*i/steps))
			var buf bytes.Buffer
			var opt gif.Options
			opt.NumColors = 256

			gif.Encode(&buf, img, &opt)
			g, _ := gif.DecodeAll(&buf)
			images = append(images, g.Image[0])
			delays = append(delays, 50)
		}

		gif.EncodeAll(w, &gif.GIF{
			Image: images,
			Delay: delays,
		})
	}
}

// ServeView serves the mandelbrot UI page.
func (h *Handler) ServeView(w http.ResponseWriter, r *http.Request) {
	data := struct {
		assets.CommonData
	}{
		CommonData: assets.CommonData{Version: version.Version, Flag: version.Flag},
	}

	if err := assets.ExecuteTemplate(w, "mandelbrot.html", data); err != nil {
		logger.Log.Error(err, "[mandelbrot] executing template")
	}
}

func form2float64(form []string, def float64) (f float64) {
	f = def
	if form != nil {
		f, _ = strconv.ParseFloat(form[0], 64)
	}
	return
}

func mandelbrot(xmin, ymin, xmax, ymax float64) image.Image {
	const (
		width, height = 512, 512
	)

	img := image.NewRGBA(image.Rect(0, 0, width, height))
	for py := 0; py < height; py++ {
		y := float64(py)/height*(ymax-ymin) + ymin
		for px := 0; px < width; px++ {
			x := float64(px)/width*(xmax-xmin) + xmin
			z := complex(x, y)
			img.Set(px, py, m(z))
		}
	}

	return img
}

func m(z complex128) color.Color {
	const (
		iterations = 200
		contrast   = 15
	)

	var v complex128
	for n := uint8(0); n < iterations; n++ {
		v = v*v + z
		if cmplx.Abs(v) > 2 {
			r, g, b := color.YCbCrToRGB(255, 255-contrast*n, 255-contrast*n)
			return color.RGBA{r, g, b, 255}
		}
	}
	return color.Black
}

